["events"] = "UPDATE_UI_WIDGET, UNIT_POWER_UPDATE:player",
["subeventPrefix"] = "SPELL",
["custom"] = "function(states, e, w)\n    if e == \"STATUS\" or e == \"UNIT_POWER_UPDATE\" then\n      aura_env.vigor = UnitPower(\"player\", Enum.PowerType.AlternateMount)\n      if aura_env.vigor == UnitPowerMax(\"player\", Enum.PowerType.AlternateMount) then\n        for _, state in pairs(states) do\n            state.show = false;\n            state.changed = true;\n        end\n      end\n    elseif e == \"UPDATE_UI_WIDGET\" and w then\n      if w.widgetSetID == 283 then\n        local widgetInfo = C_UIWidgetManager.GetFillUpFramesWidgetVisualizationInfo(w.widgetID)\n        \n        if widgetInfo then\n            for i=1, widgetInfo.numTotalFrames do\n                states[i] = states[i] or {}\n                local s = states[i]\n                \n                s.show = true\n                s.changed = true\n                s.progressType = 'static'\n                s.total = widgetInfo.fillMax\n                \n                if (widgetInfo.numFullFrames >= i) then\n                    s.value =  widgetInfo.fillMax\n                elseif (widgetInfo.numFullFrames + 1 == i) then\n                    s.value =  widgetInfo.fillValue\n                else \n                    s.value = widgetInfo.fillMin\n                end\n            end\n        end \n      end\n    end\n    return true\n  end",
["use_unit"] = true,
["customVariables"] = "{\n   value = true\n}",
