["cooldownSwipe"] = true,
["cooldownEdge"] = false,
["actions"] = {
["start"] = {
["custom"] = "local anchorID = aura_env.region.anchorID\nif anchorID then\n    C_UnitAuras.RemovePrivateAuraAnchor(anchorID)\nend\n\nlocal self = aura_env.region\nlocal privateAnchorArgs = {\n    unitToken = \"player\",\n    auraIndex = aura_env.state.index,\n    parent = self,\n    showCountdownFrame = true,\n    showCountdownNumbers = true,\n    iconInfo = {\n        iconAnchor = {\n            point = \"CENTER\",\n            relativeTo = self,\n            relativePoint = \"CENTER\",\n            offsetX = 0,\n            offsetY = 0\n        },\n        iconWidth = self:GetWidth(),\n        iconHeight = self:GetHeight()\n    }\n}\n\naura_env.region.anchorID = C_UnitAuras.AddPrivateAuraAnchor(privateAnchorArgs)",
["do_sound"] = false,
["sound_kit_id"] = "",
["do_custom"] = true,
["sound"] = " custom",
},
["init"] = {
["custom"] = "if not C_UnitAuras.AddPrivateAuraAppliedSound then return end\nif not WeakAuras.IsOptionsOpen() then\n    aura_env.privateAuras = {\n        [1228114] = \"Drop.ogg\", --Netherbreaker\n        [1237108] = \"Targeted.ogg\", --Twilight Massacre\n        [1225316] = \"Drop.ogg\", --Galactic Smash\n        [1226601] = \"Drop.ogg\", --Galactic Smash\n        [1226602] = \"Drop.ogg\", --Galactic Smash\n        [1248128] = \"Drop.ogg\", --Galactic Smash\n        [1226018] = \"Targeted.ogg\", --Starkiller Swing\n    }\n    for spellID, sound in pairs(aura_env.privateAuras) do\n        C_UnitAuras.AddPrivateAuraAppliedSound({\n                unitToken = \"player\",\n                spellID = spellID,\n                soundFileName = \"Interface\\\\AddOns\\\\SharedMedia_Causese\\\\sound\\\\\"..sound..\".ogg\",\n                outputChannel = \"MASTER\",\n        })\n    end\nend",
["do_custom"] = true,
},
["finish"] = {
["do_sound"] = false,
["custom"] = "local anchorID = aura_env.region.anchorID\nif anchorID then\n    C_UnitAuras.RemovePrivateAuraAnchor(anchorID)\nend",
["stop_sound"] = false,
["sound_kit_id"] = "200485",
["do_custom"] = true,
["sound"] = " custom",
["sound_channel"] = "Master",
},
},
