["displayText_format_p_time_dynamic_threshold"] = 60,
["customText"] = "function()\n    local specID = GetSpecialization()\n    if not specID then return \"Unknown Spec\" end\n    \n    local specInfo = GetSpecializationInfo(specID)\n    if not specInfo then return \"Unknown Spec\" end\n    \n    local specIDNum = select(1, GetSpecializationInfo(specID))\n    if not specIDNum then return \"Unknown Spec\" end\n    \n    local configID = C_ClassTalents.GetLastSelectedSavedConfigID(specIDNum)\n    if not configID then return \"No Loadout\" end\n    \n    local configInfo = C_Traits.GetConfigInfo(configID)\n    if not configInfo or not configInfo.name then return \"Unnamed Loadout\" end\n    \n    local header = \"|cffC41E3AWrong Spec Dummy!|r\\n\"\n    local body = \"|cffFF7C0AYou're in |r|cffC41E3A\" .. configInfo.name .. \"|r |cffFF7C0Aspec!|r\"\n    local string = header .. body\n    \n    return string\nend",
["shadowYOffset"] = -1,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://wago.io/9l6F2qtex/8",
["actions"] = {
["start"] = {
},
["init"] = {
["custom"] = "_G.WSD_LoadoutOptions = {}\n\nlocal specIndex = GetSpecialization()\nif specIndex then\n    local specID = select(1, GetSpecializationInfo(specIndex))\n    if specID then\n        for _, id in ipairs(C_ClassTalents.GetConfigIDsBySpecID(specID) or {}) do\n            local info = C_Traits.GetConfigInfo(id)\n            if info and info.name then\n                _G.WSD_LoadoutOptions[info.name] = info.name\n            end\n        end\n    end\nend",
["do_custom"] = true,
},
["finish"] = {
},
},
["triggers"] = {
{
["trigger"] = {
["use_alwaystrue"] = true,
["duration"] = "15",
["subeventPrefix"] = "SPELL",
["debuffType"] = "HELPFUL",
["use_unit"] = true,
["type"] = "custom",
["use_absorbHealMode"] = true,
["subeventSuffix"] = "_CAST_START",
["names"] = {
},
["dynamicDuration"] = false,
["event"] = "Conditions",
["custom_type"] = "event",
["customDuration"] = "\n\n",
["custom"] = "function(event, ...)\n    local errorMsg = \"|cff00bfff[WSD]|r |cffff2020Error!|r |cffffff00You did not set a spec for this dungeon.|r\"\n    \n    local specID = GetSpecialization()\n    if not specID then return end\n    \n    local specIDNum = select(1, GetSpecializationInfo(specID))\n    if not specIDNum then return end\n    \n    local configID = C_ClassTalents.GetLastSelectedSavedConfigID(specIDNum)\n    if not configID then return end\n    \n    local configInfo = C_Traits.GetConfigInfo(configID)\n    if not configInfo or not configInfo.name then return end\n    \n    local playerSpecName = string.lower(configInfo.name)\n    local function isWrong(expectedName)\n        return expectedName and expectedName ~= \"\" and playerSpecName ~= string.lower(expectedName)\n    end\n    \n    local inInstance, instanceType = IsInInstance()\n    if not inInstance then\n        if isWrong(aura_env.config.wsd_gen.wsd_gen_ow) then\n            return true\n        end\n        return false\n    end\n    \n    local _, instanceTypeActual, difficultyID, _, _, _, _, instanceID = GetInstanceInfo()\n    \n    if instanceTypeActual == \"party\" then\n        if difficultyID ~= 8 and difficultyID ~= 23 then return false end\n        \n        local mplusConfigMap = {\n            [2661] = aura_env.config.wsd_mp.wsd_mp_1,\n            [2651] = aura_env.config.wsd_mp.wsd_mp_2,\n            [2649] = aura_env.config.wsd_mp.wsd_mp_3,\n            [2648] = aura_env.config.wsd_mp.wsd_mp_4,\n            [2773] = aura_env.config.wsd_mp.wsd_mp_5,\n            [2293] = aura_env.config.wsd_mp.wsd_mp_6,\n            [2097] = aura_env.config.wsd_mp.wsd_mp_7,\n            [1594] = aura_env.config.wsd_mp.wsd_mp_8,\n        }\n        \n        local dungeonSpec = mplusConfigMap[instanceID]\n        \n        if dungeonSpec and dungeonSpec ~= \"\" then\n            if isWrong(aura_env.config.wsd_gen.mp) and isWrong(dungeonSpec) then\n                return true\n            end\n        end\n        return false\n    elseif instanceTypeActual == \"raid\" and instanceID == 2769 then\n        if isWrong(aura_env.config.wsd_gen.wsd_gen_raids) then\n            return true\n        end\n        return false\n    elseif instanceTypeActual == \"scenario\" then\n        if isWrong(aura_env.config.wsd_gen.wsd_gen_delv) then\n            return true\n        end\n        return false\n    elseif instanceTypeActual == \"pvp\" then\n        if isWrong(aura_env.config.wsd_gen.wsd_gen_pvp) then\n            return true\n        end\n        return false\n    end\n    \n    return false\nend",
