["custom"] = "function(allstates, event, unit, _, spellID)    \n    if event == \"UNIT_TARGET\" and UnitIsUnit(unit..\"target\", \"player\")\n    then\n        local _,_,_,_,expirationTime,_,_,_,spellId = UnitCastingInfo(unit)\n        local guid = UnitGUID(unit)\n        if spellId == 1237694 then\n            allstates:Update(guid, {\n                    progressType = \"timed\", \n                    duration = expirationTime / 1000 - GetTime(),\n                    expirationTime = expirationTime / 1000,\n                    autoHide = true,\n            })\n        end\n    elseif event == \"UNIT_SPELLCAST_STOP\" and spellID == 1237694 then\n        allstates:Remove(UnitGUID(unit))\n    end\nend",
