["Lunar Effect - Loot Master"] = {
["outline"] = "OUTLINE",
["wagoID"] = "545iusHIy",
["xOffset"] = 0,
["displayText"] = "%c",
["customText"] = "function()\n    if not aura_env.tierList then\n        return \"Tier List: (Empty)\"\n    end\n    \n    local classColors = {\n        [\"DEATHKNIGHT\"] = \"C41F3B\",\n        [\"DEMONHUNTER\"] = \"A330C9\",\n        [\"DRUID\"] = \"FF7D0A\",\n        [\"EVOKER\"] = \"33937F\",\n        [\"HUNTER\"] = \"AAD372\",\n        [\"MAGE\"] = \"3FC7EB\",\n        [\"MONK\"] = \"00FF96\",\n        [\"PALADIN\"] = \"F58CBA\",\n        [\"PRIEST\"] = \"FFFFFF\",\n        [\"ROGUE\"] = \"FFF569\",\n        [\"SHAMAN\"] = \"0070DE\",\n        [\"WARLOCK\"] = \"8787ED\",\n        [\"WARRIOR\"] = \"C79C6E\"\n    }\n    \n    local function GetClassColor(name)\n        if not aura_env.raidClasses then return name end  -- Ensure data exists\n        \n        local class = aura_env.raidClasses[name]\n        if class and classColors[class] then\n            return \"|cFF\" .. classColors[class] .. name .. \"|r\"\n        end\n        return name\n    end\n    \n    local output = \"Tier List:\\n\"\n    for player, items in pairs(aura_env.tierList) do\n        local coloredName = GetClassColor(player)\n        output = output .. coloredName .. \": \"\n        \n        local tierCount = 0\n        for _, itemID in ipairs(items) do\n            local numericID = tonumber(itemID)\n            if numericID and aura_env.tierItemIDs[numericID] then\n                tierCount = tierCount + 1\n            end\n        end\n        output = output .. tierCount .. \"/5 Tier\\n\"\n    end\n    \n    -- List players who didn't respond\n    local missingPlayers = {}\n    for player in pairs(aura_env.raidMembers or {}) do\n        if not (aura_env.receivedResponses and aura_env.receivedResponses[player]) then\n            table.insert(missingPlayers, GetClassColor(player) .. \": |cffC41E3AMissing WA|r\")\n        end\n    end\n    \n    if #missingPlayers > 0 then\n        output = output .. \"\\nMissing Responses:\\n\" .. table.concat(missingPlayers, \"\\n\")\n    end\n    \n    return output\nend",
