{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "event",
["duration"] = "0",
["unit"] = "player",
["events"] = "CHAT_MSG_ADDON,ENCOUNTER_END,PLAYER_ENTERING_WORLD",
["check"] = "event",
["custom_hide"] = "timed",
["custom"] = "function(event, ...)\n    -- Helper: raid difficulty (returns number or nil)\n    local function raidDiff()\n        if IsInRaid() and GetRaidDifficultyID then\n            return GetRaidDifficultyID()\n        end\n    end\n    \n    -- Helper: safe split\n    local function explode(str, delimiter)\n        local result = {}\n        for match in string.gmatch(str, \"([^\"..delimiter..\"]+)\") do\n            table.insert(result, match)\n        end\n        return result\n    end\n    \n    if event == \"ENCOUNTER_END\" or event == \"PLAYER_ENTERING_WORLD\" then\n        -- choose chat channel locally (fixes W111/W113)\n        local chatChannel\n        if (raidDiff() == 17) then\n            chatChannel = \"INSTANCE_CHAT\"\n        else\n            chatChannel = \"RAID\"\n        end\n        \n        -- Request tier updates from the group\n        C_Timer.After(5, function()\n                C_ChatInfo.SendAddonMessage(\"LE_TIER\", \"le_update_tier_request\", chatChannel)\n        end)\n    end\n    \n    if event == \"CHAT_MSG_ADDON\" then\n        -- don't bind unused 'channel' (fixes W211)\n        local prefix, message, _, sender = ...\n        \n        if prefix == \"LE_TIER_MAIN\" then\n            -- Ensure tables exist\n            aura_env.receivedResponses = aura_env.receivedResponses or {}\n            aura_env.tierList = aura_env.tierList or {}\n            \n            -- Strip realm from sender (e.g., \"Name-Realm\" -> \"Name\")\n            local senderName = strsplit(\"-\", sender)\n            \n            -- Parse the incoming message\n            local data = explode(message, \":\")\n            if #data < 6 then return false end -- Ensure valid data\n            \n            local playerName = data[1]\n            local itemIDs = { unpack(data, 2, 6) }\n            \n            -- Store the response\n            aura_env.tierList[playerName] = itemIDs\n            \n            -- Track who responded (without realm)\n            aura_env.receivedResponses[senderName] = true\n            \n            return true\n        end\n        \n        if prefix == \"LE_TIER\" then\n            -- Initialize tables\n            aura_env.raidMembers = {}\n            aura_env.raidClasses = {}\n            aura_env.receivedResponses = {}\n            \n            -- Collect all raid members\n            if IsInRaid() then\n                for i = 1, GetNumGroupMembers() do\n                    local name, _, _, _, _, class = GetRaidRosterInfo(i)\n                    if name and class then\n                        -- reuse name; don't shadow (fixes W411)\n                        name = strsplit(\"-\", name)\n                        aura_env.raidMembers[name] = true\n                        aura_env.raidClasses[name] = class\n                    end\n                end\n            end\n        end\n    end\n    \n    return false\nend",
["debuffType"] = "HELPFUL",
