["realSpellName"] = 0,
["use_spellName"] = false,
["custom"] = "function(allstates, event, ...)\n    if event == \"COMBAT_LOG_EVENT_UNFILTERED\" then\n        local timestamp, subEvent, hideCaster, sourceGUID, sourceName, sourceFlags, sourceRaidFlags, destGUID, destName, destFlags, destRaidFlags, spellID = ...\n        if subEvent == \"SPELL_AURA_APPLIED\" and spellID == 460781 then\n            local state = allstates[\"\"]\n            if state then \n                if not state.guid[destGUID] then\n                    state.value = state.value + 1\n                    state.guid[destGUID] = true\n                    state.changed = true\n                    return true\n                end\n            else\n                allstates[\"\"] = {\n                    show = true,\n                    changed = true,\n                    progressType = \"static\",\n                    guid = {\n                        [destGUID] = true\n                    },\n                    value = 1,\n                }\n                return true\n            end\n        elseif subEvent == \"SPELL_AURA_REMOVED\" and spellID == 460781 then\n            local state = allstates[\"\"]\n            if state and state.guid[destGUID] then\n                state.value = state.value - 1\n                state.guid[destGUID] = nil\n                if state.value <= 0 then\n                    state.show = false\n                end\n                state.changed = true\n                return true\n            end\n        end\n    end\nend",
