},
["custom"] = "function(allstates, event, ...)\n    if event == \"COMBAT_LOG_EVENT_UNFILTERED\" then\n        local timestamp, subEvent, hideCaster, sourceGUID, sourceName, sourceFlags, sourceRaidFlags, destGUID, destName, destFlags, destRaidFlags, spellID, _,_, auraType = ...\n        if subEvent == \"SPELL_AURA_APPLIED\" \n        and spellID == 1242883 then\n            aura_env.counter = aura_env.counter + 1\n            if destGUID == WeakAuras.myGUID then\n                local role = ((aura_env.counter - 1) % 3 == 0) and \"Lead\" or \"Follow\"\n                allstates:Update(destGUID, {\n                        progressType = \"timed\",\n                        duration = 4.2,\n                        expirationTime = 4.2 + GetTime(),\n                        role = role,\n                        autoHide = true,\n                })\n            end\n        end\n    elseif event == \"UNIT_SPELLCAST_CHANNEL_STOP\" then\n        local _, _, spellID = ...\n        if spellID == 1245978 then\n            aura_env.counter = 0\n        end\n    elseif event == \"ENCOUNTER_START\" then\n        aura_env.counter = 0\n    end\nend",
