["init"] = {
["custom"] = "-- Register our prefix (make sure all players use the same one)\nC_ChatInfo.RegisterAddonMessagePrefix(\"LE_TIER\")\n\n-- Reset le_tier upon startup.\naura_env.le_tier = nil",
["do_custom"] = true,
